int main() {
    string x;
    cin >> x;
    sort(x.begin(), x.end());
    for (int i = 0; i < (int) x.size(); i++) {
        if (x[i] > '0') {
            swap(x[0], x[i]);
            break;
        }
    }
    cout << x << endl;
